{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Replace negative-score weighting with mean pairwise softplus loss and a 0.2 margin to encourage positive–negative separation. Preserve the existing sampled negatives, valid-position mask, GRU model, and training settings.",
      "edits": [
        {
          "find": "    weights = torch.softmax(valid_neg.detach(), dim=0)\n    pairwise_loss = torch.nn.functional.softplus(valid_neg - valid_pos)\n    return (weights * pairwise_loss).sum()",
          "replace": "    pairwise_loss = torch.nn.functional.softplus(0.2 + valid_neg - valid_pos)\n    return pairwise_loss.mean()"
        }
      ]
    }
  ],
  "change_summary": "Change only the learning objective to mean softplus(0.2 + negative_score - positive_score). Inference and checkpoint formats require no changes."
}
